## 3. Тести Unity Test Framework (NUnit)
```csharp
[TestFixture]
public class OpticalReflectionTests {
    [Test]
    public void Mirror45_ReflectsCorrectly_At45Degrees() {
        var direction = new float2(1, 0);
        var normal = math.normalize(new float2(-1, 1));
        var reflected = math.reflect(direction, normal);
        Assert.IsTrue(math.abs(reflected.y - 1.0f) < 0.001f);
    }

    [Test]
    public void Bounce_Limit_Prevents_Infinite_Loop() {
        var config = new GlobalOpticsConfig { MaxBounces = 5 };
        int bounceCount = 0;
        while (bounceCount < config.MaxBounces) {
            bounceCount++;
        }
        Assert.AreEqual(5, bounceCount);
    }

    [Test]
    public void SquareGrid_Alignment_Validation() {
        float step = 45.0f;
        Assert.AreEqual(0, 360 % (int)step);
    }
}
```

